package net.minecraft.nbt;
import java.util.*;
/** Models NBT type IDs and copy behavior, not binary codec or Minecraft dispatch. */
public class CompoundTag {
 private final Map<String,Object> values=new HashMap<>();
 public int getInt(String key){Object x=values.get(key);return x instanceof Number n?n.intValue():0;}
 public byte getByte(String key){Object x=values.get(key);return x instanceof Number n?n.byteValue():0;}
 public String getString(String key){return values.get(key) instanceof String s?s:"";}
 public void putInt(String key,int x){values.put(key,x);}public void putByte(String key,byte x){values.put(key,x);}
 public void putBoolean(String key,boolean x){putByte(key,(byte)(x?1:0));}public void putString(String key,String x){values.put(key,x);}
 public void putLong(String key,long x){values.put(key,x);}public void put(String key,CompoundTag x){values.put(key,x);}
 public void remove(String key){values.remove(key);}public int size(){return values.size();}
 public Set<String> getAllKeys(){return values.keySet();}
 public CompoundTag getCompound(String key){return values.get(key) instanceof CompoundTag x?x:new CompoundTag();}
 public boolean contains(String key,int type){Object x=values.get(key);return switch(type){case 1->x instanceof Byte;case 3->x instanceof Integer;case 4->x instanceof Long;case 8->x instanceof String;case 10->x instanceof CompoundTag;default->false;};}
 public CompoundTag copy(){var c=new CompoundTag();values.forEach((k,v)->c.values.put(k,v instanceof CompoundTag x?x.copy():v));return c;}
}
